        "polishing_issue_responses": {
            "present": resp_path.is_file(),
            "path": _relative_under_quest(quest_dir, resp_path)
            if resp_path.is_file()
            else "polishing_issue_responses.md",
            "latest_response_updated_at": latest_resp,
            "summaries": summaries,
        },
    }


